import sys

def find_score_distribution(n, m):
    if m == 0:
        return list(range(1, n + 1))

    # Start with the simplest increasing sequence
    a = list(range(1, n + 1))

    # Calculate the current balance
    current_balance = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if a[i] + a[j] == a[k]:
                    current_balance += 1

    # If the current balance is already m, return the sequence
    if current_balance == m:
        return a

    # Try to adjust the sequence to achieve the desired balance
    for i in range(n - 1, 0, -1):
        a[i] += 1
        new_balance = 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if a[i] + a[j] == a[k]:
                        new_balance += 1
        if new_balance == m:
            return a
        elif new_balance > m:
            a[i] -= 1
            break

    return -1

